def copy_existing_content_files_to_private_storage(apps, schema_editor):
    """Preserve uploaded content files when switching to private storage."""
    public_storage = FileSystemStorage(location=settings.MEDIA_ROOT)
    private_storage = PrivateMediaStorage()
    content_models = (
        ('Article', ('image',)),
        ('Certificate', ('image', 'document')),
        ('Expertise', ('image',)),
        ('GalleryImage', ('image',)),
        ('Project', ('image',)),
    )
    for model_name, fields in content_models:
        model = apps.get_model('content', model_name)
        for field_name in fields:
            for record in model.objects.exclude(**{field_name: ''}).iterator():
                name = getattr(record, field_name).name
                if name and public_storage.exists(name) and not private_storage.exists(name):
                    with public_storage.open(name, 'rb') as source:
                        private_storage.save(name, source)


